function saveItems() {
  const items = Array.from(document.querySelectorAll('.item')).map(item => ({
    text: item.querySelector('.item-text').textContent,
    done: item.classList.contains('done')
  }));
  localStorage.setItem('r9-items', JSON.stringify(items));
}

function loadItems() {
  const items = JSON.parse(localStorage.getItem('r9-items')) || [];
  items.forEach(item => newItem(item.text, item.done));
}

args.replace:
function newItem(taskText, isDone = false) {
  const item = document.createElement('div');
  item.classList.add('item');
  if (isDone) {
    item.classList.add('done');
  }
  const itemText = document.createElement('span');
  itemText.classList.add('item-text');
  itemText.textContent = taskText;
  item.appendChild(itemText);
  const itemRemove = document.createElement('button');
  itemRemove.textContent = 'Remove';
  itemRemove.addEventListener('click', () => removeItem(item));
  item.appendChild(itemRemove);
  list.appendChild(item);
  updateCount();
  saveItems(); // Save items to localStorage after adding a new item
}

